-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/ahtUrhgan/PUP_AF3_Puppetmaster_Blues.lua"]={["Path"]="scripts/quests/ahtUrhgan/PUP_AF3_Puppetmaster_Blues.lua",["SHA256"]="a1fb46272eebbb66ea51d631b665362c3688556ebcc6c64381d87fc76013cbde",["Text"]="-----------------------------------\n-- Puppetmaster Blues\n-----------------------------------\n-- Log ID: 6, Quest ID: 29\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PUPPETMASTER_BLUES)\n\nquest.reward =\n{\n    item  = xi.item.PUPPETRY_TAJ,\n    title = xi.title.PARAGON_OF_PUPPETMASTER_EXCELLENCE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.OPERATION_TEATIME) and\n                player:getMainJob() == xi.job.PUP and\n                player:getMainLvl() >= xi.settings.main.AF3_QUEST_LEVEL\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Iruki-Waraki'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(782)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [782] = function(player, csid, option, npc)\n                    return quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Iruki-Waraki'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress <= 2 then\n                        return quest:event(783)\n                    elseif questProgress == 3 then\n                        return quest:progressEvent(784)\n                    elseif questProgress == 4 then\n                        return quest:event(785)\n                    else\n                        return quest:progressEvent(786)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [784] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n\n                [786] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n\n            },\n        },\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Shamarhaan'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(437)\n                    elseif questProgress == 1 then\n                        return quest:event(438)\n                    elseif questProgress == 2 then\n                        return quest:progressEvent(439)\n                    else\n                        return quest:event(440)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [437] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.VALKENGS_MEMORY_CHIP)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [439] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.MOUNT_ZHAYOLM] =\n        {\n            ['qm8'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        not player:hasKeyItem(xi.keyItem.TOGGLE_SWITCH)\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.TOGGLE_SWITCH)\n                        return quest:noAction()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Sajhra'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:progressEvent(291)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [291] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n            },\n        },\n\n        [xi.zone.TALACCA_COVE] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.PUPPETMASTER_BLUES then\n                        player:delKeyItem(xi.keyItem.VALKENGS_MEMORY_CHIP)\n                        player:delKeyItem(xi.keyItem.TOGGLE_SWITCH)\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Iruki-Waraki'] =\n            {\n                onTrigger = function(player, npc)\n                    player:startEvent(787)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Promotion_Chief_Sergeant.lua"]={["Path"]="scripts/quests/ahtUrhgan/Promotion_Chief_Sergeant.lua",["SHA256"]="be2ca0e7ee41349b180ee9e881d5c36a642326d58d3d0f47d339ecb84946b110",["Text"]="-----------------------------------\n-- Promotion: Chief Sergeant\n-- Logid: 6 Questid: 96\n-- Abquhbah: !pos 35 -6 -58 50\n-- Hagakoff: !pos 82 0 -74 50\n-- Mushroom Patch:\n--[[\n    [1] = !pos 123 37 6 68\n    [2] = !pos -359 15 -425 68\n    [3] = !pos -208 9 143 68\n    [4] = !pos 117 37 -46 68\n    [5] = !pos -221 9 141 68\n    [6] = !pos -345 15 -442 68\n]]\n-----------------------------------\nlocal aydeewaID = zones[xi.zone.AYDEEWA_SUBTERRANE]\nlocal whitegateID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_CHIEF_SERGEANT)\nlocal patchStage =\n{\n    NONE      = 0,\n    HARVESTED = 1,\n    PLANTED   = 2,\n    PICKED    = 3,\n}\nlocal triggerPatch = function(player, npc)\n    --[[\n    notes: dont have KI and havent plated, recieve KI - cs 14\n    place you have picked from - cs 15\n    have KI and wasnt place you picked it, lose KI - 19, option 0\n    place you have plated but not ready yet - cs 20\n    place you placed and ready to harvest - cs 21 {[0] = amount, [3] = bonus mushroom} option = amount recieved\n    if no KI and already harvested the area - cs 18\n    have KI and cant get KI from - cs 16\n    ]]\n\n    local mushroomPatchOffset = npc:getID() - aydeewaID.npc.MUSHROOM_PATCH\n    local patch = 'MPatch'..mushroomPatchOffset\n    local mushroomVar = quest:getVar(player, patch)\n    local result = quest:messageSpecial(aydeewaID.text.NOTHING_OUT_OF_ORDINARY)\n    local time = VanadielHour()\n\n    -- Dont have KI have not picked or planted at patch\n    if\n        not player:hasKeyItem(xi.keyItem.SCOURSHROOM) and\n        mushroomVar == patchStage.NONE\n    then\n        return quest:progressEvent(14)\n\n    -- Section you have already Picked from\n    elseif mushroomVar == patchStage.HARVESTED then\n        return quest:progressEvent(15)\n\n    -- Section Planting if have KI and has not yet been touched\n    elseif\n        player:hasKeyItem(xi.keyItem.SCOURSHROOM) and\n        mushroomVar == patchStage.NONE\n    then\n        return quest:progressEvent(19)\n\n    -- planted a mushroom\n    elseif mushroomVar == patchStage.PLANTED then\n        -- Ready to harvest\n        if\n            quest:getVar(player, 'MPatch_Time') <= VanadielUniqueDay() and\n            not player:needToZone()\n        then\n            local timeBonus = 1\n            local bonus = math.randomInt(1, 100) >= 75 and 5 or 0\n            if time >= 4 and time <= 6 and math.randomInt(1, 100) >= 50 then\n                timeBonus = 2\n            end\n\n            return quest:progressEvent(21, { [0] = timeBonus, [3] = bonus })\n        -- Not ready to harvest\n        else\n            return quest:progressEvent(20)\n        end\n\n    -- Picked already\n    elseif mushroomVar == patchStage.PICKED then\n        return quest:progressEvent(18)\n\n    -- player has KI and has not been harvested already\n    elseif\n        player:hasKeyItem(xi.keyItem.SCOURSHROOM) and\n        mushroomVar == patchStage.NONE\n    then\n        return quest:progressEvent(16)\n    end\n\n    return result\nend\n\nlocal unsetPatches = function(player)\n    for i = 0, 5 do\n        local patch = 'MPatch'..i\n        local patchTime = 'MPatch_Time'..i\n        quest:setVar(player, patch, 0)\n        quest:setVar(player, patchTime, 0)\n    end\nend\n\nquest.reward =\n{\n    item    = xi.item.IMPERIAL_MYTHRIL_PIECE,\n    keyItem = xi.keyItem.CS_WILDCAT_BADGE,\n    title   = xi.title.CHIEF_SERGEANT,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getVar('AssaultPromotion') >= 25 and\n            player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_SERGEANT_MAJOR) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] = quest:progressEvent(5060),\n\n            onEventFinish =\n            {\n                [5060] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n    {\n        -- Started quest has a reminder, trigger Hagakoff to progress\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 0\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] = quest:progressEvent(5062):oncePerZone(),\n\n            ['Hagakoff'] = quest:progressEvent(5067),\n\n            onEventFinish =\n            {\n                [5067] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n    {\n        -- Talked to Hagakoff and told to go back to Abquhbah\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 1\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] = quest:progressEvent(5068),\n\n            onEventFinish =\n            {\n                [5068] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n    {\n        -- Talked to Abquhbah and told to go back to Hagakoff again\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 2\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] = quest:progressEvent(5069):oncePerZone(),\n\n            ['Hagakoff'] = quest:progressEvent(5063),\n\n            onEventFinish =\n            {\n                [5063] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 3\n        end,\n\n        [xi.zone.AYDEEWA_SUBTERRANE] =\n        {\n            ['Mushroom_Patch'] =\n            {\n                onTrigger = function(player, npc)\n                    return triggerPatch(player, npc)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [14] = function(player, csid, option, npc)\n                    local mushroomPatchOffset = npc:getID() - aydeewaID.npc.MUSHROOM_PATCH\n\n                    quest:setVar(player, 'MPatch'..mushroomPatchOffset, patchStage.HARVESTED)\n                    player:addKeyItem(xi.keyItem.SCOURSHROOM)\n                end,\n\n                [19] = function(player, csid, option, npc)\n                    if option == 0 then\n                        local mushroomPatchOffset = npc:getID() - aydeewaID.npc.MUSHROOM_PATCH\n\n                        quest:setVar(player, 'MPatch'..mushroomPatchOffset, patchStage.PLANTED)\n                        quest:setVar(player, 'MPatch_Time'..mushroomPatchOffset, VanadielUniqueDay() + 1)\n                        player:needToZone(true)\n                        player:delKeyItem(xi.keyItem.SCOURSHROOM)\n                    end\n                end,\n\n                [21] = function(player, csid, option, npc)\n                    if option ~= 100 then\n                        local mushrooms = quest:getVar(player, 'Option')\n                        local mushroomPatchOffset = npc:getID() - aydeewaID.npc.MUSHROOM_PATCH\n                        local amount = option + mushrooms\n\n                        if amount > 5 then\n                            quest:messageSpecial(aydeewaID.text.NO_MORE_SPROUTS)\n                            quest:messageSpecial(aydeewaID.text.NO_MORE_SPROUTS + 1, 0, 5)\n                        end\n\n                        quest:setVar(player, 'MPatch'..mushroomPatchOffset, patchStage.PICKED)\n                        quest:setVar(player, 'Option', utils.clamp(amount, 1, 5))\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] =\n            {\n                onTrigger = function(player, npc)\n                    local mushrooms = quest:getVar(player, 'Option')\n                    local polished = quest:getVar(player, 'Stage')\n\n                    if mushrooms > 0 then\n                        return quest:progressEvent(5061, { [0] = polished, [1] = mushrooms })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5061] = function(player, csid, option, npc)\n                    if option < 11 then\n                        local polished = quest:getVar(player, 'Stage')\n\n                        quest:setVar(player, 'Stage', quest:getVar(player, 'Option') + polished)\n                        quest:setVar(player, 'Option', 0)\n                        unsetPatches(player)\n                    elseif option >= 20 then\n                        if option >= 30 and player:getFreeSlotsCount() < 2 then\n                            quest:messageSpecial(whitegateID.text.ITEM_CANNOT_BE_OBTAINED + 4)\n                            return\n                        end\n\n                        if quest:complete(player) then\n                            if option >= 30 then\n                                npcUtil.giveItem(player, xi.item.IMPERIAL_GOLD_PIECE)\n                            end\n\n                            player:setCharVar('AssaultPromotion', 0)\n                            player:messageSpecial(whitegateID.text.PROMOTION_CHIEF_SERGEANT)\n                            player:delKeyItem(xi.keyItem.SCOURSHROOM)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Promotion_Corporal.lua"]={["Path"]="scripts/quests/ahtUrhgan/Promotion_Corporal.lua",["SHA256"]="3961690efc4d85f5d2756c947bfa271e60de31f1df4b44160fffddaa200e5c94",["Text"]="-----------------------------------\n-- Promotion: Corporal\n-- Naja Salaheem !pos 26 -8 -45.5 50\n-- LogID: 6 QuestID: 93\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_CORPORAL)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.C_WILDCAT_BADGE,\n    title   = xi.title.CORPORAL,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getCharVar('AssaultPromotion') >= 25 and\n            player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_LANCE_CORPORAL) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5045, { text_table = 0 }),\n\n            onEventFinish =\n            {\n                [5045] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.QUARTZ_TRANSMITTER)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            player:hasKeyItem(xi.keyItem.QUARTZ_TRANSMITTER)\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5047, { text_table = 0 }):oncePerZone(),\n        },\n\n        [xi.zone.BHAFLAU_THICKETS] =\n        {\n            ['Warhorse_Hoofprint'] =\n            {\n                onTrigger = function(player, npc)\n                    player:delKeyItem(xi.keyItem.QUARTZ_TRANSMITTER)\n                    quest:setVar(player, 'Prog', 2)\n                    return quest:messageSpecial(zones[player:getZoneID()].text.WARHORSE_HOOFPRINT + 1, xi.keyItem.QUARTZ_TRANSMITTER)\n                end,\n            },\n        },\n        [xi.zone.CAEDARVA_MIRE] =\n        {\n            ['Warhorse_Hoofprint'] =\n            {\n                onTrigger = function(player, npc)\n                    player:delKeyItem(xi.keyItem.QUARTZ_TRANSMITTER)\n                    quest:setVar(player, 'Prog', 4)\n                    return quest:messageSpecial(zones[player:getZoneID()].text.WARHORSE_HOOFPRINT + 1, xi.keyItem.QUARTZ_TRANSMITTER)\n                end,\n            },\n        },\n        [xi.zone.MOUNT_ZHAYOLM] =\n        {\n            ['Warhorse_Hoofprint'] =\n            {\n                onTrigger = function(player, npc)\n                    player:delKeyItem(xi.keyItem.QUARTZ_TRANSMITTER)\n                    quest:setVar(player, 'Prog', 3)\n                    return quest:messageSpecial(zones[player:getZoneID()].text.WARHORSE_HOOFPRINT + 1, xi.keyItem.QUARTZ_TRANSMITTER)\n                end,\n            },\n        },\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            ['Warhorse_Hoofprint'] =\n            {\n                onTrigger = function(player, npc)\n                    player:delKeyItem(xi.keyItem.QUARTZ_TRANSMITTER)\n                    quest:setVar(player, 'Prog', 1)\n                    return quest:messageSpecial(zones[player:getZoneID()].text.WARHORSE_HOOFPRINT + 1, xi.keyItem.QUARTZ_TRANSMITTER)\n                end,\n            },\n        },\n\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            not player:hasKeyItem(xi.keyItem.QUARTZ_TRANSMITTER)\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] =\n            {\n                onTrigger = function(player, npc)\n                    local hoofprintZone = quest:getVar(player, 'Prog')\n                    return quest:progressEvent(5046, { [0] = hoofprintZone, text_table = 0 })\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5046] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:setVar('AssaultPromotion', 0)\n                        player:delKeyItem(xi.keyItem.LC_WILDCAT_BADGE)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Promotion_First_Lieutenant.lua"]={["Path"]="scripts/quests/ahtUrhgan/Promotion_First_Lieutenant.lua",["SHA256"]="76951d8471ca683a9f4b8139aa6a2496eb42914f71b005cb22c311a276c43b93",["Text"]="-----------------------------------\n-- Promotion First Lieutenant\n-----------------------------------\n-- LogID: 6 QuestID: 98\n-- Abquhbah: !pos 35.5 -6.6 -58 50\n-----------------------------------\nlocal ID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\n-----------------------------------\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_FIRST_LIEUTENANT)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.FL_WILDCAT_BADGE,\n    title   = xi.title.FIRST_LIEUTENANT,\n}\n\nquest.sections =\n{\n    -- Trigger to start quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getCharVar('AssaultPromotion') >= 25 and\n            player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_SECOND_LIEUTENANT) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            onTriggerAreaEnter =\n            {\n                [12] = function(player, triggerArea)\n                    return quest:progressEvent(5080, { text_table = 0 })\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5080] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n    -- Trigger to give reminder, trade coins to give academy tuition\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 0 and\n            vars.Wait == 0\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, { { xi.item.IMPERIAL_GOLD_PIECE, 5 } }) then\n                        return quest:progressEvent(5081, { text_table = 0 })\n                    end\n                end,\n\n                onTrigger = quest:event(5087, { text_table = 0 }):oncePerZone(),\n            },\n\n            onEventFinish =\n            {\n                [5081] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Wait', VanadielUniqueDay())\n                end,\n            },\n        },\n    },\n    -- Minigame Counterespionage\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 0 and\n            vars.Wait > 0\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] =\n            {\n                onTrigger = function(player, npc)\n                    local wait = quest:getVar(player, 'Wait')\n                    local redo = quest:getVar(player, 'Stage') == 0 and 0 or 1\n\n                    if wait < VanadielUniqueDay() then\n                        return quest:progressEvent(5082, { [0] = redo, text_table = 0 })\n                    else\n                        return quest:event(5088, { text_table = 0 })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5082] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'Prog', 1)\n                        quest:setVar(player, 'Stage', 0)\n                    else\n                        quest:setVar(player, 'Stage', 1)\n                    end\n\n                    quest:setVar(player, 'Wait', VanadielUniqueDay())\n                end,\n            },\n        },\n    },\n    -- Minigame Cipher\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 1\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] =\n            {\n                onTrigger = function(player, npc)\n                    local wait = quest:getVar(player, 'Wait')\n                    local redo = quest:getVar(player, 'Stage') == 0 and 0 or 1\n\n                    if wait <= VanadielUniqueDay() then\n                        return quest:progressEvent(5083, { [0] = redo, text_table = 0 })\n                    else\n                        return quest:event(5088, { [0] = 1, text_table = 0 })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5083] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'Prog', 2)\n                        quest:setVar(player, 'Stage', 0)\n                    else\n                        quest:setVar(player, 'Stage', 1)\n                    end\n\n                    quest:setVar(player, 'Wait', VanadielUniqueDay())\n                end,\n            },\n        },\n    },\n    -- Minigame rock, paper, scissors\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 2\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] =\n            {\n                onTrigger = function(player, npc)\n                    local wait = quest:getVar(player, 'Wait')\n                    local redo = quest:getVar(player, 'Stage') == 0 and 0 or 1\n\n                    if wait <= VanadielUniqueDay() then\n                        return quest:progressEvent(5084, { [0] = redo, text_table = 0 })\n                    else\n                        return quest:event(5088, { text_table = 0 })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5084] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 3)\n                        quest:setVar(player, 'Stage', 0)\n                    else\n                        quest:setVar(player, 'Stage', 1)\n                    end\n\n                    quest:setVar(player, 'Wait', VanadielUniqueDay())\n                end,\n            },\n        },\n    },\n    -- Graduation setup\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 3\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] =\n            {\n                onTrigger = function(player, npc)\n                    local wait = quest:getVar(player, 'Wait') < VanadielUniqueDay() and 1 or 0\n\n                    return quest:event(5089, { [0] = wait, text_table = 0 }):importantOnce()\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5089] = function(player, csid, option, npc)\n                    local gameHour = VanadielHour()\n                    if gameHour >= 15 and gameHour < 17 then\n                        quest:setVar(player, 'Prog', 4)\n                        player:needToZone(true)\n                    end\n                end,\n            },\n        },\n    },\n    -- Graduation setup after zone\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 4\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] =\n            {\n                onTrigger = function(player, npc)\n                    local gameHour = VanadielHour()\n\n                    if gameHour >= 15 and gameHour < 17 and not player:needToZone() then\n                        return quest:progressEvent(5085, { text_table = 0 })\n                    else\n                        return quest:event(5089, { [0] = 1, text_table = 0 })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5085] = function(player, csid, option, npc)\n                    quest:complete(player)\n                    player:delKeyItem(xi.keyItem.SL_WILDCAT_BADGE)\n                    quest:messageSpecial(ID.text.FIRST_LIEUTENANT)\n                    player:setCharVar('AssaultPromotion', 0)\n                end,\n            },\n        },\n    },\n}\nreturn quest\n"},["scripts/quests/ahtUrhgan/Promotion_Lance_Corporal.lua"]={["Path"]="scripts/quests/ahtUrhgan/Promotion_Lance_Corporal.lua",["SHA256"]="ab860dbbc144014aca2b226e1defcffb3c6b0c11b355f5b1a09ed19e77223fa9",["Text"]="-----------------------------------\n-- Promotion: Lance Corporal\n-- Logid: 6 Quest: 92\n-- Abquhbah:                 !pos 35.5 -6.6 -58 50\n-- Nafiwaa:                  !pos -74 -6 126 50\n-- Mythralline Wellspring 1: !pos -92 -15 -339 51\n-- Mythralline Wellspring 2: !pos -218 -15 -388 51\n-- Mythralline Wellspring 3: !pos 181 -23 268 51\n-- Mythralline Wellspring 4: !pos 259 -23 132 51\n-- Mythralline Wellspring 5: !pos 181 -15 373 52\n-- Prog: running total of player's test tube contents\n-- Option: what mixture was turned in to the guild\n-----------------------------------\nlocal ahturhganID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\nlocal bhaflauID    = zones[xi.zone.BHAFLAU_THICKETS]\nlocal wajaomID     = zones[xi.zone.WAJAOM_WOODLANDS]\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_LANCE_CORPORAL)\n\nlocal stage =\n{\n    START     = 0,\n    FIRST_MIX = 1,\n    REMIX     = 2,\n    WAIT      = 3,\n}\n\nlocal tube =\n{\n    ONE   = 1,\n    TWO   = 2,\n    THREE = 3,\n    FOUR  = 4,\n    FIVE  = 5,\n}\n\nlocal tubeKeyItems =\n{\n    [tube.ONE]   = { filledTube = xi.keyItem.TEST_TUBE_1, emptyTube = xi.keyItem.EMPTY_TEST_TUBE_1 },\n    [tube.TWO]   = { filledTube = xi.keyItem.TEST_TUBE_2, emptyTube = xi.keyItem.EMPTY_TEST_TUBE_2 },\n    [tube.THREE] = { filledTube = xi.keyItem.TEST_TUBE_3, emptyTube = xi.keyItem.EMPTY_TEST_TUBE_3 },\n    [tube.FOUR]  = { filledTube = xi.keyItem.TEST_TUBE_4, emptyTube = xi.keyItem.EMPTY_TEST_TUBE_4 },\n    [tube.FIVE]  = { filledTube = xi.keyItem.TEST_TUBE_5, emptyTube = xi.keyItem.EMPTY_TEST_TUBE_5 },\n}\n\nlocal fillLevel =\n{\n    FULL            = 0,\n    ONE_THIRD_USED  = 1,\n    TWO_THIRDS_USED = 2,\n    EMPTY           = 3,\n}\n\nlocal function getFluidLevel(player, tubeNum, var)\n    local allTubes = utils.mask.splitBits(quest:getVar(player, var), 2)\n\n    return allTubes[tubeNum] or 0\nend\n\nlocal function getFilledTubeCount(player)\n    local tubeCount = 0\n\n    for _, keyItems in ipairs(tubeKeyItems) do\n        if player:hasKeyItem(keyItems.filledTube) then\n            tubeCount = tubeCount + 1\n        end\n    end\n\n    return tubeCount\nend\n\nlocal function canFillTube(player, tubeNum)\n    return player:hasKeyItem(tubeKeyItems[tubeNum].emptyTube) or\n    (quest:getVar(player, 'Stage') == stage.REMIX and getFluidLevel(player, tubeNum, 'Prog') ~= fillLevel.FULL)\nend\n\nlocal function fillTestTube(player, tubeNum)\n    local bitPosOne = (tubeNum * 2) - 1\n    local bitPosTwo = bitPosOne - 1\n\n    quest:unsetVarBit(player, 'Prog', bitPosOne)\n    quest:unsetVarBit(player, 'Prog', bitPosTwo)\n\n    if player:hasKeyItem(tubeKeyItems[tubeNum].emptyTube) then\n        player:delKeyItem(tubeKeyItems[tubeNum].emptyTube)\n        player:addKeyItem(tubeKeyItems[tubeNum].filledTube)\n    end\n\n    if quest:getVar(player, 'Stage') == stage.FIRST_MIX then\n        player:messageSpecial(zones[player:getZoneID()].text.KEYITEM_OBTAINED, tubeKeyItems[tubeNum].filledTube)\n    else\n        player:messageSpecial(zones[player:getZoneID()].text.WELLSPRING + 1)\n    end\nend\n\nlocal function getQuestReward(player)\n    local tubeAmounts = {} -- calculate how many thirds of each tube were used, multiply by the tube's density and add them all together.\n\n    for tubeNum = tube.ONE, tube.FIVE do\n        table.insert(tubeAmounts, getFluidLevel(player, tubeNum, 'Option'))\n    end\n\n    local mythrallineQuality = 0\n    local densities = -- densities are constant based on the hints and consistent results.\n    {\n        [tube.ONE]   = 0.5, -- \"...appears to be very light.\"\n        [tube.TWO]   = 1.5, -- \"...is at the same level as tube #4.\"\n        [tube.THREE] = 2.0, -- \"...appears to be very dense.\"\n        [tube.FOUR]  = 1.5, -- \"...caused a reaction three times faster than the sample in tube #1.\"\n        [tube.FIVE]  = 1.0, -- \"...has a density is equal to half that of the sample with the highest concentration..\"\n    }\n\n    for tubeNum, contents in ipairs(tubeAmounts) do\n        mythrallineQuality = mythrallineQuality + (contents * densities[tubeNum])\n    end\n\n    -- Final Mythralline Quality\n    -- 1.0 - 1.5 = Silver\n    -- 2.0 - 3.5 = Mythril\n    -- 4.0 - 5.5 = Gold\n    -- 6.0 - 9.5 = Platinum\n    -- 10.0      = Luminium\n    -- 10.5      = Smoke\n\n    local reward\n    local rewardTiers =\n    {\n        luminium = { item = xi.item.IMPERIAL_GOLD_PIECE, amount = 2 },\n        platinum =\n        {\n            { item = xi.item.IMPERIAL_MYTHRIL_PIECE, amount = math.randomInt(3, 4) },\n            { item = xi.item.IMPERIAL_GOLD_PIECE, amount = 1 },\n        },\n    }\n\n    if mythrallineQuality == 10 then\n        reward = rewardTiers.luminium\n    elseif mythrallineQuality >= 6 and mythrallineQuality <= 9.5 then\n        reward = rewardTiers.platinum[math.randomInt(1, #rewardTiers.platinum)]\n    end\n\n    return reward\nend\n\nquest.reward =\n{\n    keyItem = xi.keyItem.LC_WILDCAT_BADGE,\n    title   = xi.title.LANCE_CORPORAL,\n}\n\nquest.sections =\n{\n    { -- Start: Trigger Abquhbah\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getCharVar('AssaultPromotion') >= 25 and\n            player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_SUPERIOR_PRIVATE) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] = quest:progressEvent(5030, { text_table = 0 }),\n\n            onEventFinish =\n            {\n                [5030] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n    { -- 1st Stage: Trigger Nafiwaa and recieve 5 KI empty test tubes\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Stage == stage.START\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] = quest:event(5032):importantOnce(),\n\n            ['Nafiwaa'] = quest:progressEvent(5035, { text_table = 0 }),\n\n            onEventFinish =\n            {\n                [5035] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Stage', stage.FIRST_MIX)\n                    npcUtil.giveKeyItem(player, { xi.keyItem.EMPTY_TEST_TUBE_1, xi.keyItem.EMPTY_TEST_TUBE_2,\n                        xi.keyItem.EMPTY_TEST_TUBE_3, xi.keyItem.EMPTY_TEST_TUBE_4, xi.keyItem.EMPTY_TEST_TUBE_5 })\n                end,\n            },\n        },\n    },\n    { -- 2nd (and optional 3rd) Stage: Go to Mythralline Wellsprings and fill tubes; Trigger Nafiwaa to do mini game and mix mythralline\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            (vars.Stage == stage.FIRST_MIX or vars.Stage == stage.REMIX)\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] = quest:event(5033):importantOnce(),\n\n            ['Nafiwaa'] =\n            {\n                onTrigger = function(player, npc)\n                    local currentStage = quest:getVar(player, 'Stage')\n                    local tubeContents = quest:getVar(player, 'Prog')\n                    local isRemix = currentStage == stage.REMIX and 1 or 0\n                    local emptyTubes = 0\n\n                    if currentStage == stage.FIRST_MIX then\n                        local filledTubeCount = getFilledTubeCount(player)\n\n                        if filledTubeCount == 0 then\n                            return quest:event(5036)\n                        elseif filledTubeCount < 5 then -- must gather all 5 tubes on first mix\n                            return quest:event(5037, { [1] = filledTubeCount })\n                        end\n                    elseif currentStage == stage.REMIX then\n                        local totalThirds = 15\n\n                        for tubeNum = tube.ONE, tube.FIVE do\n                            totalThirds = totalThirds - getFluidLevel(player, tubeNum, 'Prog')\n                        end\n\n                        if totalThirds < 2 then -- not enough liquid to mix anything\n                            return quest:event(5036)\n                        end\n                    end\n\n                    for tubeNum, keyItems in ipairs(tubeKeyItems) do\n                        if player:hasKeyItem(keyItems.emptyTube) then\n                            emptyTubes = utils.mask.setBit(emptyTubes, tubeNum - 1, 1)\n                        end\n                    end\n\n                    return quest:progressEvent(5038, { [2] = tubeContents, [5] = emptyTubes, [7] = isRemix, text_table = 0 })\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5038] = function(player, csid, option, npc)\n                    local remainingTubeContents, mask = utils.mask.varSplit(option, 16)\n\n                    local result = bit.rshift(mask, 14)\n\n                    if result == 2 then -- accept the results, turn in to guild\n                        local startingContents = quest:getVar(player, 'Prog')\n\n                        quest:setVar(player, 'Stage', stage.WAIT)\n                        quest:setVar(player, 'Wait', VanadielUniqueDay() + 1)\n                        quest:setVar(player, 'Option', remainingTubeContents - startingContents)\n\n                        for keyItem = xi.keyItem.EMPTY_TEST_TUBE_1, xi.keyItem.TEST_TUBE_5 do\n                            if player:hasKeyItem(keyItem) then\n                                player:delKeyItem(keyItem)\n                            end\n                        end\n\n                    elseif result == 1 then -- threw it out\n                        quest:setVar(player, 'Stage', stage.REMIX)\n                        quest:setVar(player, 'Prog', remainingTubeContents)\n\n                        for tubeNum, tubeKeyItem in ipairs(tubeKeyItems) do\n                            if\n                                getFluidLevel(player, tubeNum, 'Prog') == fillLevel.EMPTY and\n                                player:hasKeyItem(tubeKeyItem.filledTube)\n                            then\n                                player:delKeyItem(tubeKeyItem.filledTube)\n                                player:addKeyItem(tubeKeyItem.emptyTube)\n                            end\n                        end\n                    end\n                end,\n            },\n        },\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            ['Mythralline_Wellspring'] =\n            {\n                onTrigger = function(player, npc)\n                    local offset = npc:getID() - wajaomID.npc.WELLSPRING\n                    if canFillTube(player, tube.ONE + offset) then\n                        return quest:progressEvent(4 + offset)\n                    end\n\n                    return quest:messageSpecial(wajaomID.text.WELLSPRING + 3)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [4] = function(player, csid, option, npc)\n                    fillTestTube(player, tube.ONE)\n                end,\n\n                [5] = function(player, csid, option, npc)\n                    fillTestTube(player, tube.TWO)\n                end,\n\n                [6] = function(player, csid, option, npc)\n                    fillTestTube(player, tube.THREE)\n                end,\n\n                [7] = function(player, csid, option, npc)\n                    fillTestTube(player, tube.FOUR)\n                end,\n            },\n        },\n        [xi.zone.BHAFLAU_THICKETS] =\n        {\n            ['Mythralline_Wellspring'] =\n            {\n                onTrigger = function(player, npc)\n                    if canFillTube(player, tube.FIVE) then\n                        return quest:progressEvent(10)\n                    end\n\n                    return quest:messageSpecial(bhaflauID.text.WELLSPRING + 3)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10] = function(player, csid, option, npc)\n                    fillTestTube(player, tube.FIVE)\n                end,\n            },\n        },\n    },\n    { -- Complete: after game day wait, enter region\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Stage == stage.WAIT and\n            vars.Option > 0\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Nafiwaa'] = quest:event(5039),\n\n            ['Abquhbah'] = quest:event(5034):importantOnce(),\n\n            onTriggerAreaEnter =\n            {\n                [3] = function(player, triggerArea)\n                    if quest:getVar(player, 'Wait') <= VanadielUniqueDay() then\n                        return quest:progressEvent(5031, { text_table = 0 })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5031] = function(player, csid, option, npc)\n                    local reward = getQuestReward(player)\n\n                    if reward then\n                        if not npcUtil.giveItem(player, { { reward.item, reward.amount } }) then\n                            return\n                        end\n                    end\n\n                    quest:complete(player)\n                    quest:messageSpecial(ahturhganID.text.LANCE_CORPORAL)\n                    player:setCharVar('AssaultPromotion', 0)\n                    player:delKeyItem(xi.keyItem.SP_WILDCAT_BADGE)\n                end,\n            },\n        },\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            ['Mythralline_Wellspring'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:messageSpecial(wajaomID.text.WELLSPRING + 2)\n                end,\n            },\n        },\n        [xi.zone.BHAFLAU_THICKETS] =\n        {\n            ['Mythralline_Wellspring'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:messageSpecial(bhaflauID.text.WELLSPRING + 2)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Promotion_Private_First_Class.lua"]={["Path"]="scripts/quests/ahtUrhgan/Promotion_Private_First_Class.lua",["SHA256"]="f1120834578031b73b895cae4819e17755cf06c61fa9bd0ce8ab7002c3faf33d",["Text"]="-----------------------------------\n-- Promotion: Private First Class\n-- Log ID: 6, Quest ID: 90\n-- Naja Salaheem !pos 26 -8 -45.5 50\n-----------------------------------\nlocal ID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_PRIVATE_FIRST_CLASS)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.PFC_WILDCAT_BADGE,\n    title   = xi.title.PRIVATE_FIRST_CLASS,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:getCharVar('AssaultPromotion') >= 25\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5000, { text_table = 0 }),\n\n            onEventFinish =\n            {\n                [5000] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(5001, { text_table = 0 })\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.IMP_WING, 1 } }) then\n                        return quest:progressEvent(5002, { text_table = 0 })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5002] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:setCharVar('AssaultPromotion', 0)\n                        player:tradeComplete()\n                        player:delKeyItem(xi.keyItem.PSC_WILDCAT_BADGE)\n                        player:messageSpecial(ID.text.PRIVATE_FIRST_CLASS)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Promotion_Second_Lieutenant.lua"]={["Path"]="scripts/quests/ahtUrhgan/Promotion_Second_Lieutenant.lua",["SHA256"]="33d1858bfdc98d6c0af722bf2bc33d8b87e1518725964d00f985c50e9ba4c4b2",["Text"]="-----------------------------------\n-- Promotion Second Lieutenant\n-- Abquhbah: !pos 35.5 -6.6 -58 50\n-----------------------------------\nlocal ID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_SECOND_LIEUTENANT)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.SL_WILDCAT_BADGE,\n    title   = xi.title.SECOND_LIEUTENANT,\n}\n\nquest.sections =\n{\n    -- Trigger to start quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getCharVar('AssaultPromotion') >= 25 and\n            player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_CHIEF_SERGEANT) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] = quest:progressEvent(5071),\n\n            onTriggerAreaEnter =\n            {\n                [3] = function(player, triggerArea)\n                    return quest:progressEvent(5071)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5071] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n    -- Trigger to give reminder, trade coins to give academy tuition\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 0\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.IMPERIAL_GOLD_PIECE, 3 } }) then\n                        return quest:progressEvent(5073)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(5072):oncePerZone()\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5073] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 1)\n                    npcUtil.giveKeyItem(player, xi.keyItem.OFFICER_ACADEMY_MANUAL)\n                end,\n            },\n        },\n    },\n    -- Begin 1st game, Trigger for reminder, trade coins to start\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 1\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.IMPERIAL_MYTHRIL_PIECE, 2 } }) then\n                        return quest:progressEvent(5075)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getLocalVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(5074)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5074] = function(player, csid, option, npc)\n                    quest:setLocalVar(player, 'Prog', 1)\n                end,\n\n                [5075] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setLocalVar(player, 'Prog', 0)\n                    if option == 1 then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n            },\n        },\n    },\n    -- starts 2nd game: trigger for reminder, trade coins to progress\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 2\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.IMPERIAL_MYTHRIL_PIECE, 2 } }) then\n                        return quest:progressEvent(5076)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getLocalVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(5074)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5074] = function(player, csid, option, npc)\n                    quest:setLocalVar(player, 'Prog', 1)\n                end,\n\n                [5076] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n    -- completes 2nd game: trigger for reminder, trade item to progress\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 3\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] =\n            {\n                onTrade = function(player, npc, trade)\n                    local beastmenItems =\n                    {\n                        xi.item.MACUAHUITL_M1, xi.item.MAMOOL_JA_COLLAR, xi.item.MAMOOL_JA_HELM,\n                        xi.item.JADAGNA_M1, xi.item.JANUWIYAH_M1, xi.item.TARIQAH_M1,\n                        xi.item.TROLL_PAULDRON, xi.item.TROLL_VAMBRACE, xi.item.LAMIAN_ARMLET,\n                        xi.item.LAMIAN_KAMAN_M1, xi.item.QUTRUB_GORGET\n                    }\n\n                    for _, requiredTrade in pairs(beastmenItems) do\n                        if npcUtil.tradeHasExactly(trade, { requiredTrade }) then\n                            return quest:progressEvent(5077)\n                        end\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(5079):oncePerZone()\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5077] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setLocalVar(player, 'Prog', 0)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n    -- 3rd game: trigger for reminder, trade coins to play\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 4\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.IMPERIAL_MYTHRIL_PIECE, 2 } }) then\n                        return quest:progressEvent(5078)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getLocalVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(5074)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5074] = function(player, csid, option, npc)\n                    quest:setLocalVar(player, 'Prog', 1)\n                end,\n\n                [5078] = function(player, csid, option, npc)\n                    quest:setLocalVar(player, 'Prog', 0)\n                    player:confirmTrade()\n                    if option == 1 then\n                        if quest:complete(player) then\n                            player:setCharVar('AssaultPromotion', 0)\n                            player:delKeyItem(xi.keyItem.CS_WILDCAT_BADGE)\n                            quest:messageSpecial(ID.text.SECOND_LIEUTENANT)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Promotion_Sergeant.lua"]={["Path"]="scripts/quests/ahtUrhgan/Promotion_Sergeant.lua",["SHA256"]="8a6f8d72d84219240a4a73eb25b1ae36e51c69fdd74ceb0c8cde74df8313be4a",["Text"]="-----------------------------------\n-- Promotion: Sergeant\n-- Log ID: 6, Quest ID: 94\n-- Naja Salaheem      : !pos 26 -8 -45.5 50\n-- Region 10 Whitegate: !pos -80 0 0 50\n-- Region 1 Nashmau   : !pos 0 0 -40 53\n-- Totoroon           : !pos -13 0 -24 53\n-- qm11               : !pos 195 2 -616 79\n-----------------------------------\nlocal whitegateID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_SERGEANT)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.S_WILDCAT_BADGE,\n    title   = xi.title.SERGEANT,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:getCharVar('AssaultPromotion') >= 25 and\n            player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_CORPORAL) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5055),\n\n            onEventFinish =\n            {\n                [5055] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5058):oncePerZone(),\n\n            onTriggerAreaEnter =\n            {\n                [10] = function(player, triggerArea)\n                    return quest:progressEvent(5056)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5056] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5058):oncePerZone(),\n        },\n\n        [xi.zone.NASHMAU] =\n        {\n            onTriggerAreaEnter =\n            {\n                [1] = function(player, triggerArea)\n                    if VanadielUniqueDay() > quest:getVar(player, 'Stage') then\n                        return quest:progressEvent(303)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [303] = function(player, csid, option, npc)\n                    if option == 2 then\n                        quest:setVar(player, 'Prog', 2)\n                    else\n                        quest:setVar(player, 'Stage', VanadielUniqueDay() + 1)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5058):oncePerZone(),\n        },\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Totoroon'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.BOWL_OF_SUTLAC) then\n                        return quest:progressEvent(304)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:event(252)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [304] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5058):oncePerZone(),\n        },\n\n        [xi.zone.CAEDARVA_MIRE] =\n        {\n            ['qm11'] = quest:progressEvent(20),\n\n            onEventFinish =\n            {\n                [20] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 4\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5057),\n\n            onEventFinish =\n            {\n                [5057] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:setCharVar('AssaultPromotion', 0)\n                        player:messageSpecial(whitegateID.text.PROMOTION_SERGEANT)\n                        player:delKeyItem(xi.keyItem.C_WILDCAT_BADGE)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Promotion_Sergeant_Major.lua"]={["Path"]="scripts/quests/ahtUrhgan/Promotion_Sergeant_Major.lua",["SHA256"]="7f14772e86d8a2fa8e5f64a4b7865c95d6d67261fffa5e4c1351291137e4d19d",["Text"]="-----------------------------------\n-- Promotion: Promotion Sergeant Major\n-- Naja Salaheem !pos 26 -8 -45.5 50\n-----------------------------------\nlocal whitegateID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_SERGEANT_MAJOR)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.SM_WILDCAT_BADGE,\n    title   = xi.title.SERGEANT_MAJOR,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getCharVar('AssaultPromotion') >= 25 and\n            player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_SERGEANT) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5048),\n\n            onEventFinish =\n            {\n                [5048] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', VanadielUniqueDay())\n                    if option == 2 then\n                        quest:setVar(player, 'Stage', 1)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        -- Didnt pass 1st game and has to redo\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Stage == 0 and\n            vars.Prog < VanadielUniqueDay()\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5049),\n\n            onEventFinish =\n            {\n                [5049] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', VanadielUniqueDay())\n                    if option == 2 then\n                        -- passed 1st mini game, onto 2nd\n                        quest:setVar(player, 'Stage', 1)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        -- Passed 1st mini game, start 2nd\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Stage == 1 and\n            vars.Prog < VanadielUniqueDay()\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5050),\n\n            onEventFinish =\n            {\n                [5050] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', VanadielUniqueDay())\n                    if option == 2 then\n                        -- passed mini game, onto 3rd game\n                        quest:setVar(player, 'Stage', 3)\n                    else\n                        -- failed and has to do again\n                        quest:setVar(player, 'Stage', 2)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        -- Didnt pass 2nd game, redo\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Stage == 2 and\n            vars.Prog < VanadielUniqueDay()\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5051),\n\n            onEventFinish =\n            {\n                [5051] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', VanadielUniqueDay())\n                    if option == 2 then\n                        -- passed mini game, onto 3rd game\n                        quest:setVar(player, 'Stage', 3)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        -- Passed 2nd mini game, start 3rd\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Stage == 3 and\n            vars.Prog < VanadielUniqueDay()\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5052),\n\n            onEventFinish =\n            {\n                [5052] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', VanadielUniqueDay())\n                    if option == 2 then\n                        -- passed mini game, You did it!\n                        quest:setVar(player, 'Stage', 5)\n                    else\n                        -- failed and has to do again\n                        quest:setVar(player, 'Stage', 4)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        -- Didnt pass 3rd game, Redo\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Stage == 4 and\n            vars.Prog < VanadielUniqueDay()\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5053),\n\n            onEventFinish =\n            {\n                [5053] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', VanadielUniqueDay())\n                    if option == 2 then\n                        -- passed mini game, complete\n                        quest:setVar(player, 'Stage', 5)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        -- Passed all games and 1 game day wait\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Stage == 5 and\n            vars.Prog < VanadielUniqueDay()\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5054),\n\n            onEventFinish =\n            {\n                [5054] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:setCharVar('AssaultPromotion', 0)\n                        player:delKeyItem(xi.keyItem.S_WILDCAT_BADGE)\n                        player:messageSpecial(whitegateID.text.PROMOTION_SERGEANT_MAJOR)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Promotion_Superior_Private.lua"]={["Path"]="scripts/quests/ahtUrhgan/Promotion_Superior_Private.lua",["SHA256"]="e640623b420d806d8eacac76d5e86f1b70b5c2db3dca3d7f1da14efabedd8046",["Text"]="-----------------------------------\n-- Promotion: Superior Private\n-- Log ID: 6, Quest ID: 91\n-- Naja Salaheem !pos 26 -8 -45.5 50\n-----------------------------------\nlocal ahturhganID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_SUPERIOR_PRIVATE)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.SP_WILDCAT_BADGE,\n    title   = xi.title.SUPERIOR_PRIVATE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:getCharVar('AssaultPromotion') >= 25 and\n            player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PROMOTION_PRIVATE_FIRST_CLASS) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5020, { text_table = 0 }),\n\n            onEventFinish =\n            {\n                [5020] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setMustZone(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and not player:hasKeyItem(xi.keyItem.DARK_RIDER_HOOFPRINT)\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getMustZone(player) then\n                        return quest:event(5021, { [0] = 1, [1] = 1, text_table = 0 }):oncePerZone()\n                    else\n                        return quest:event(5021, { text_table = 0 }):oncePerZone()\n                    end\n                end\n            }\n        },\n\n        [xi.zone.BHAFLAU_THICKETS] =\n        {\n            ['Warhorse_Hoofprint'] = quest:keyItem(xi.keyItem.DARK_RIDER_HOOFPRINT)\n        },\n        [xi.zone.CAEDARVA_MIRE] =\n        {\n            ['Warhorse_Hoofprint'] = quest:keyItem(xi.keyItem.DARK_RIDER_HOOFPRINT)\n        },\n        [xi.zone.MOUNT_ZHAYOLM] =\n        {\n            ['Warhorse_Hoofprint'] = quest:keyItem(xi.keyItem.DARK_RIDER_HOOFPRINT)\n        },\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            ['Warhorse_Hoofprint'] = quest:keyItem(xi.keyItem.DARK_RIDER_HOOFPRINT)\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and player:hasKeyItem(xi.keyItem.DARK_RIDER_HOOFPRINT)\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] = quest:progressEvent(5022, { text_table = 0 }),\n\n            onEventFinish =\n            {\n                [5022] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:setCharVar('AssaultPromotion', 0)\n                        player:delKeyItem(xi.keyItem.PFC_WILDCAT_BADGE)\n                        player:delKeyItem(xi.keyItem.DARK_RIDER_HOOFPRINT)\n                        player:messageSpecial(ahturhganID.text.SUPERIOR_PRIVATE)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Rat_Race.lua"]={["Path"]="scripts/quests/ahtUrhgan/Rat_Race.lua",["SHA256"]="4fab1c6de0a1a17ba2a218befea641d28052e28d71f0cfba097cb29f1c6ba400",["Text"]="-----------------------------------\n-- Rat Race\n-----------------------------------\n-- Log ID: 6, Quest ID: 66\n-- Kakkaroon      : !pos 13.245 0.000 -25.307 53\n-- Nadee Periyaha : !pos -10.802 0.000 -1.198 50\n-- Cacaroon       : !pos -72.026 0.000 -82.337 50\n-- Ququroon       : !pos -2.400 -1 66.824 53\n-- Kyokyoroon     : !pos 18.020 -6.000 10.467 53\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.RAT_RACE)\n\nquest.reward =\n{\n    item =\n    {\n        { xi.item.IMPERIAL_GOLD_PIECE,    2 },\n        { xi.item.IMPERIAL_MYTHRIL_PIECE, 2 },\n        { xi.item.IMPERIAL_SILVER_PIECE,  3 },\n    },\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Kakkaroon'] =\n            {\n                onTrigger = quest:progressEvent(308),\n            },\n\n            onEventFinish =\n            {\n                [308] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Nadee_Periyaha'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:progressEvent(849)\n                    elseif questProgress == 2 then\n                        return quest:event(851)\n                    elseif questProgress >= 3 then\n                        return quest:event(852)\n                    end\n                end,\n            },\n\n            ['Cacaroon'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        npcUtil.tradeHas(trade, xi.item.IMPERIAL_BRONZE_PIECE)\n                    then\n                        return quest:progressEvent(850)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 2 then\n                        return quest:event(853)\n                    elseif questProgress >= 3 then\n                        return quest:event(854)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [849] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [850] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Kakkaroon'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 6 then\n                        return quest:progressEvent(312)\n                    else\n                        return quest:event(313)\n                    end\n                end,\n            },\n\n            ['Kyokyoroon'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 5 and\n                        npcUtil.tradeHasExactly(trade, xi.item.BOWL_OF_NASHMAU_STEW)\n                    then\n                        return quest:progressEvent(311)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 6 then\n                        return quest:event(316)\n                    end\n                end,\n            },\n\n            ['Ququroon'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 4 and\n                        npcUtil.tradeHasExactly(trade, { xi.item.AHTAPOT, xi.item.ISTAKOZ, xi.item.ISTAVRIT_1, xi.item.ISTIRIDYE, xi.item.MERCANBALIGI })\n                    then\n                        return quest:progressEvent(310)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 3 then\n                        return quest:progressEvent(309)\n                    elseif questProgress == 4 then\n                        return quest:event(242)\n                    elseif questProgress >= 5 then\n                        return quest:event(315)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [309] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n\n                [310] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.BOWL_OF_NASHMAU_STEW) then\n                        player:confirmTrade()\n                        quest:setVar(player, 'Prog', 5)\n                    end\n                end,\n\n                [311] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 6)\n                end,\n\n                [312] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Kakkaroon']  = quest:event(314),\n            ['Kyokyoroon'] = quest:event(317),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Rock_Bottom.lua"]={["Path"]="scripts/quests/ahtUrhgan/Rock_Bottom.lua",["SHA256"]="46f6fab23cfbdeee153aabaaeef622452703e7e8650564f7f05b33d6d074faa4",["Text"]="-----------------------------------\n-- Rock Bottom\n-- !pos 838.243 -14.475 231.871 61\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.ROCK_BOTTOM)\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.MOUNT_ZHAYOLM] =\n        {\n            ['blank11'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(7)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [7] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MOUNT_ZHAYOLM] =\n        {\n            ['blank11'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.tradeMatches(trade, { { xi.item.PICKAXE, 1 } })\n                    then\n                        return quest:progressEvent(8)\n                    elseif\n                        not player:needToZone() and\n                        quest:getVar(player, 'Prog') == 2 and\n                        (\n                            npcUtil.tradeMatches(trade, { { xi.item.MYTHRIL_PICK, 1 } }) or\n                            npcUtil.tradeMatches(trade, { { xi.item.MYTHRIL_PICK_HQ, 1 } })\n                        )\n                    then\n                        return quest:progressEvent(9, { [0] = trade:getItemId() })\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:messageSpecial(zones[player:getZoneID()].text.NOTHING_HAPPENS)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [8] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    player:needToZone(true)\n                end,\n\n                [9] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        if player:hasKeyItem(xi.keyItem.MAP_OF_MOUNT_ZHAYOLM) then\n                            npcUtil.giveCurrency(player, 'gil', 2000)\n                        else\n                            npcUtil.giveKeyItem(player, xi.keyItem.MAP_OF_MOUNT_ZHAYOLM)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Saga_of_the_Skyserpent.lua"]={["Path"]="scripts/quests/ahtUrhgan/Saga_of_the_Skyserpent.lua",["SHA256"]="6e1fcfe06f22ccd0a3e91f18d23cb1f8ff1c7b7b5bf5ba2d5958ba16a4b52599",["Text"]="-----------------------------------\n-- Saga of the Skyserpent\n-- Log: 6, Quest: 43\n-- Fari-Wari: !pos 80 -6 -137 50\n-- qm7:       !pos -11 8 -185 62\n-- Biyaada:   !pos -65.802 -6.999 69.273 48\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.SAGA_OF_THE_SKYSERPENT)\n\nquest.reward =\n{\n    item = xi.item.IMPERIAL_GOLD_PIECE,\n    title = xi.title.SKYSERPENT_AGGRANDIZER\n}\n\nquest.sections =\n{\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:progressEvent(823, { text_table = 0 }),\n\n            onEventFinish =\n            {\n                [823] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.AL_ZAHBI] =\n        {\n            ['Biyaada'] = quest:event(278),\n        },\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:event(829),\n        },\n\n        [xi.zone.HALVUNG] =\n        {\n            ['qm7'] =\n            {\n                onTrigger = function(player, npc)\n                    quest:setVar(player, 'Prog', 1)\n                    return quest:keyItem(xi.keyItem.LILAC_RIBBON)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.AL_ZAHBI] =\n        {\n            ['Biyaada'] = quest:event(278),\n        },\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:progressEvent(953, { text_table = 0 }),\n\n            onEventFinish =\n            {\n                [953] = function(player, csid, option, npc)\n                    player:setPos(0, 0, 0, 0, xi.zone.WAJAOM_WOODLANDS)\n                end,\n            },\n        },\n\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 1 then\n                    return 12\n                end\n            end,\n\n            onEventFinish =\n            {\n                [12] = function(player, csid, option, npc)\n                    player:startEvent(13)\n                end,\n\n                [13] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    quest:setVar(player, 'Stage', VanadielUniqueDay())\n                    player:delKeyItem(xi.keyItem.LILAC_RIBBON)\n                    player:setPos(80, -6, -123, 65, xi.zone.AHT_URHGAN_WHITEGATE)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.AL_ZAHBI] =\n        {\n            ['Biyaada'] = quest:event(279),\n        },\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:progressEvent(825, { text_table = 0 }),\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Stage') < VanadielUniqueDay() then\n                        return quest:progressEvent(825, { text_table = 0 })\n                    else\n                        return quest:event(833)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [825] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addCurrency('imperial_standing', 1000)\n                        player:messageSpecial(zones[player:getZoneID()].text.BESIEGED_OFFSET)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Soothing_Waters.lua"]={["Path"]="scripts/quests/ahtUrhgan/Soothing_Waters.lua",["SHA256"]="30d90b3dcf3b9d280639d0405d016094591bfe43a0610b18ec820255caaeee66",["Text"]="-----------------------------------\n-- Soothing Waters\n-----------------------------------\n-- Logid 6 Questid 47\n-- Fari-Wari    : !pos 80 -6 -137 50\n-- Eunheem      : !pos -56 0 -3 50\n-- Nadeey       : !pos 80 0 55 50\n-- Mihli Aliapoh: !pos -22.615 -7 78.907 48\n-- qm10         : !pos 352 2 376 68\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.SOOTHING_WATERS)\n\nquest.reward =\n{\n    item = xi.item.IMPERIAL_GOLD_PIECE,\n    title = xi.title.SPRINGSERPENT_SENTRY\n}\n\nquest.sections =\n{\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.ODE_TO_THE_SERPENTS)\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:progressEvent(894, { text_table = 0 }),\n\n            onEventFinish =\n            {\n                [894] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:replaceEvent(906),\n            ['Eunheem'] = quest:progressEvent(895, { text_table = 0 }),\n\n            onEventFinish =\n            {\n                [895] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:replaceEvent(906),\n            ['Eunheem'] = quest:replaceEvent(907),\n            ['Nadeey'] = quest:progressEvent(896, { text_table = 0 }),\n\n            onEventFinish =\n            {\n                [896] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:replaceEvent(906),\n            ['Eunheem'] = quest:replaceEvent(907),\n        },\n\n        [xi.zone.AL_ZAHBI] =\n        {\n            ['Mihli_Aliapoh'] = quest:progressEvent(289),\n\n            onEventFinish =\n            {\n                [289] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:replaceEvent(906),\n            ['Eunheem'] = quest:replaceEvent(907),\n        },\n\n        [xi.zone.AYDEEWA_SUBTERRANE] =\n        {\n            ['qm10'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.TUFT_OF_COLORFUL_HAIR) then\n                        return quest:progressCutscene(34)\n                    end\n                end,\n            },\n            onEventFinish =\n            {\n                [34] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                    player:confirmTrade()\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 4\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:progressEvent(897, { text_table = 0 }),\n            ['Eunheem'] = quest:replaceEvent(907),\n\n            onEventFinish =\n            {\n                [897] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addCurrency('imperial_standing', 500)\n                        player:messageSpecial(zones[player:getZoneID()].text.BESIEGED_OFFSET)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Eunheem'] = quest:replaceEvent(285),\n        },\n\n        [xi.zone.AL_ZAHBI] =\n        {\n            ['Rughadjeen'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:replaceEvent(284, { [0] = xi.besieged.getMercenaryRank(player) })\n                end,\n            },\n            ['Gadalar'] = quest:replaceEvent(285),\n            ['Mihli_Aliapoh'] = quest:replaceEvent(286),\n            ['Zazarg'] = quest:replaceEvent(287),\n            ['Najelith'] = quest:replaceEvent(288),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Striking_a_Balance.lua"]={["Path"]="scripts/quests/ahtUrhgan/Striking_a_Balance.lua",["SHA256"]="4829ec63313f111df79da4da0d219d96eb0909c547a423fe25cfb6a6084b6201",["Text"]="-----------------------------------\n-- Striking a Balance\n-----------------------------------\n-- Log ID: 6, Quest ID: 63\n-- Wazyih:   !pos -94 -6 -93 50\n-- Saliyahf: !pos -60 0 65 50\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.STRIKING_A_BALANCE)\n\nlocal positionTable =\n{\n    [1] = {  53,    0,  60 },\n    [2] = { -70,    6,  40 },\n    [3] = { -40,    6,  70 },\n    [4] = {  18,    0, -30 },\n    [5] = { -13,    0, -40 },\n    [6] = {  39, -0.5, 116 },\n    [7] = {  20,    0, -50 },\n}\n\nquest.reward =\n{\n    item = { { xi.item.IMPERIAL_BRONZE_PIECE, 3 } },\n}\n\nquest.sections =\n{\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Wazyih'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getLocalVar(player, 'Option') == 0 then\n                        return quest:progressEvent(684)\n                    else\n                        return quest:event(685)\n                    end\n                end,\n            },\n\n            ['Saliyahf'] = quest:progressEvent(686),\n\n            onEventFinish =\n            {\n                [684] = function(player, csid, option, npc)\n                    quest:setLocalVar(player, 'Option', 1)\n                end,\n\n                [686] = function(player, csid, option, npc)\n                    quest:setLocalVar(player, 'Option', 0)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Saliyahf'] = quest:replaceEvent(687),\n\n            ['Wazyih'] = quest:progressEvent(688),\n\n            onEventFinish =\n            {\n                [688] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Saliyahf'] = quest:replaceEvent(687),\n\n            ['Wazyih'] = quest:replaceEvent(689),\n\n            onTriggerAreaEnter =\n            {\n                [9] = function(player, triggerArea)\n                    return quest:progressEvent(690)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [690] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Saliyahf'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getLocalVar(player, 'Option') == 0 then\n                        return quest:replaceEvent(692)\n                    else\n                        return quest:replaceEvent(693)\n                    end\n                end,\n            },\n\n            ['Wazyih'] = quest:progressEvent(691),\n\n            onEventFinish =\n            {\n                [691] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [692] = function(player, csid, option, npc)\n                    quest:setLocalVar(player, 'Option', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Saliyahf'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getLocalVar(player, 'Option') == 0 then\n                        return quest:replaceEvent(692)\n                    else\n                        return quest:replaceEvent(693)\n                    end\n                end,\n            },\n\n            ['Wazyih'] = quest:replaceEvent(694),\n\n            onEventFinish =\n            {\n                [692] = function(player, csid, option, npc)\n                    quest:setLocalVar(player, 'Option', 1)\n                end,\n            },\n        },\n\n        [xi.zone.AL_ZAHBI] =\n        {\n            ['blank_striking_a_balance'] =\n            {\n                onTrigger = function(player, npc)\n                    quest:setVar(player, 'Prog', 4)\n                    local newPosition = npcUtil.pickNewPosition(npc:getID(), positionTable)\n                    npc:setPos(newPosition.x, newPosition.y, newPosition.z)\n                    return quest:keyItem(xi.keyItem.MUNAHDAS_PACKAGE)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 4\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 695\n            end,\n\n            onEventFinish =\n            {\n                [695] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.MUNAHDAS_PACKAGE)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 5\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Saliyahf'] = quest:progressEvent(696),\n\n            ['Wazyih'] = quest:replaceEvent(697),\n\n            onEventFinish =\n            {\n                [696] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Such_Sweet_Sorrow.lua"]={["Path"]="scripts/quests/ahtUrhgan/Such_Sweet_Sorrow.lua",["SHA256"]="ecd67e22483a3d597a92c953423b4beb1cf4dd3123a87ab8ebd6695f515f011e",["Text"]="-----------------------------------\n-- Such Sweet Sorrow\n-----------------------------------\n-- Log ID: 6, Quest ID: 13\n-- Dabhuh: !pos 97.939 0 -91.530 50\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.SUCH_SWEET_SORROW)\n\nquest.reward =\n{\n    item = xi.item.MERROW_NO_17_LOCKET,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Dabhuh'] = quest:progressEvent(582, { text_table = 0 }),\n\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Option') == 2 then\n                    return { 956, 0 }\n                end\n            end,\n\n            onEventFinish =\n            {\n                [582] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                    player:setPos(43.493, 5.325, -699.828, 90, xi.zone.CAEDARVA_MIRE)\n                end,\n\n                [956] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Option', 0)\n                end,\n            },\n        },\n\n        [xi.zone.CAEDARVA_MIRE] =\n        {\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Option') == 1 then\n                    return 29\n                end\n            end,\n\n            onEventFinish =\n            {\n                [29] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 2)\n                    player:setPos(100.023, 0, -91.762, 125, xi.zone.AHT_URHGAN_WHITEGATE)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Dabhuh'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(584, { text_table = 0 })\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { xi.item.MERROW_SCALE }) then\n                        return quest:progressEvent(583, { text_table = 0 })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [583] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Dabhuh'] = quest:event(584, { text_table = 0 }),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/The_Die_is_Cast.lua"]={["Path"]="scripts/quests/ahtUrhgan/The_Die_is_Cast.lua",["SHA256"]="54c24608d704cad7affc3ce4ce96d4e37d485dfefeadc0287d446fae623063cd",["Text"]="-----------------------------------\n-- The Die is Cast\n-- Random Ring\n-----------------------------------\n-- Log ID: 6, Quest ID: 16\n-- Ratihb: !pos 75.225 -6.000 -137.203 50\n-- Ekhu Pesshyadha: !pos -13.043 0.999 103.423 50\n-- Jijiroon: !pos 15.913 0.000 -32.676 53\n-- qm9: !pos 311.088 -3.674 170.124 54\n-----------------------------------\n\nlocal ID = zones[xi.zone.ARRAPAGO_REEF]\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.THE_DIE_IS_CAST)\n\nquest.reward =\n{\n    item  = xi.item.RANDOM_RING,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ratihb'] = quest:progressEvent(591),\n\n            onEventFinish =\n            {\n                [591] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 0\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ekhu_Pesshyadha'] = quest:progressEvent(592),\n\n            onEventFinish =\n            {\n                [592] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 1\n        end,\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Jijiroon'] = quest:progressEvent(245),\n\n            onEventFinish =\n            {\n                [245] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 2\n        end,\n\n        [xi.zone.ARRAPAGO_REEF] =\n        {\n            ['qm9'] = quest:progressEvent(212),\n\n            onEventFinish =\n            {\n                [212] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 3\n        end,\n\n        [xi.zone.ARRAPAGO_REEF] =\n        {\n            ['qm9'] =\n            {\n                onTrigger = function(player, npc)\n                    if npcUtil.popFromQM(player, npc, ID.mob.BUKKI, { hide = 0 }) then\n                        return quest:messageSpecial(ID.text.SPINE_CHILL)\n                    end\n                end,\n            },\n\n            ['Bukki'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 4\n        end,\n\n        [xi.zone.ARRAPAGO_REEF] =\n        {\n            ['qm9'] = quest:progressEvent(213),\n\n            onEventFinish =\n            {\n                [213] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                    npcUtil.giveKeyItem(player, xi.keyItem.BAG_OF_GOLD_PIECES)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 5\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ratihb'] = quest:progressEvent(593),\n\n            onEventFinish =\n            {\n                [593] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.BAG_OF_GOLD_PIECES)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/The_Prankster.lua"]={["Path"]="scripts/quests/ahtUrhgan/The_Prankster.lua",["SHA256"]="c7b7a7f5648320588ec80dc751acdb048aa56d7ac66e61b37b33d9f54030e268",["Text"]="-----------------------------------\n-- The Prankster\n-- LogID: 6, QuestID: 60\n-- Ahaadah !pos -70 -6 105 50\n-- Aht Whitegate region 11\n-- Aht Whitegate region 12\n-- qm3 !pos 460.166 -14.920 256.214 52\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.THE_PRANKSTER)\nlocal ID = zones[xi.zone.BHAFLAU_THICKETS]\n\nquest.reward =\n{\n    keyItem = xi.keyItem.MAP_OF_CAEDARVA_MIRE,\n}\n\nquest.sections =\n{\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ahaadah'] = quest:progressEvent(1),\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 0\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ahaadah'] = quest:event(15),\n\n            onTriggerAreaEnter =\n            {\n                [11] = function(player, triggerArea)\n                    return quest:progressEvent(2)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 1\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ahaadah'] = quest:event(16),\n\n            onTriggerAreaEnter =\n            {\n                [12] = function(player, triggerArea)\n                    return quest:progressEvent(3)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3] = function(player, csid, option, npc)\n                    return quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 2\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ahaadah'] = quest:event(17),\n        },\n\n        [xi.zone.BHAFLAU_THICKETS] =\n        {\n            ['qm3'] =\n            {\n                onTrigger = function(player, npc)\n                    if not GetMobByID(ID.mob.PLAGUE_CHIGOE):isSpawned() then\n                        return quest:progressCutscene(1)\n                    end\n                end,\n            },\n\n            ['Plague_Chigoe'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    npcUtil.popFromQM(player, npc, ID.mob.PLAGUE_CHIGOE, { hide = 0 })\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 3\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ahaadah'] = quest:event(17),\n        },\n\n        [xi.zone.BHAFLAU_THICKETS] =\n        {\n            ['qm3'] = quest:progressCutscene(2),\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ahaadah'] = quest:event(18):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/The_Prince_and_the_Hopper.lua"]={["Path"]="scripts/quests/ahtUrhgan/The_Prince_and_the_Hopper.lua",["SHA256"]="f2b0b44d443900c183325cc5bf27bbc005e063a43a2e25de7f69bbf93bf7604e",["Text"]="-----------------------------------\n-- The Prince and the Hopper\n-----------------------------------\n-- Log ID: 6, Quest ID: 67\n-- Maudaal          : !pos -147.198 1.8 -3.121 50\n-- Toads Footprint2 : !pos 216.1 -23.818 -102.464 65\n-- Toads Footprint1 : !pos -42.9248 5.9847 -100.2972 65\n-----------------------------------\nlocal mamookID = zones[xi.zone.MAMOOK]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.THE_PRINCE_AND_THE_HOPPER)\n\nlocal spawnedMobs =\n{\n    mamookID.mob.MIKILULU,\n    mamookID.mob.MIKIRURU,\n    mamookID.mob.NIKILULU,\n    mamookID.mob.MIKILURU,\n    mamookID.mob.MIKIRULU,\n    mamookID.mob.POROGGO_CASANOVA,\n}\n\nquest.reward =\n{\n    item = xi.item.CHANOIXS_GORGET\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Maudaal'] = quest:progressEvent(889),\n\n            onEventFinish =\n            {\n                [889] = function(player, csid, option, npc)\n                    if option == 2 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 0 then\n                    local xPos = player:getXPos()\n                    local yPos = player:getYPos()\n                    local zPos = player:getZPos()\n\n                    if\n                        xPos >= 680.0 and yPos >= -19.0 and zPos >= 218.0 and\n                        xPos <= 691.0 and yPos <= -14.0 and zPos <= 221.0\n                    then\n                        return 513\n                    end\n                elseif quest:getVar(player, 'Prog') == 2 then\n                    return 20\n                end\n            end,\n\n            onEventFinish =\n            {\n                [20] = function(player, csid, option, npc) -- end of zone in cutscene\n                    quest:setVar(player, 'Prog', 3)\n                    -- zone the person back to mamook\n                    player:setPos(216.100, -23.818, -102.464, 0, 65)\n                end,\n\n                [513] = function(player, csid, option, npc) -- end of zone in cutscene\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.MAMOOK] =\n        {\n            ['Toads_Footprint2'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(222)\n                    end\n                end,\n            },\n\n            ['Toads_Footprint1'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 4 then\n                        return quest:progressEvent(223)\n                    elseif questProgress == 5 then\n                        -- missing special spawn animation, cannot find in packet capture.\n                        if npcUtil.popFromQM(player, npc, spawnedMobs, { hide = 1 }) then\n                            player:messageSpecial(mamookID.text.IMPENDING_BATTLE)\n                        end\n                    elseif questProgress == 6 then\n                        return quest:progressEvent(225)\n                    end\n                end,\n            },\n\n            ['Poroggo_Casanova'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 5 then\n                        quest:setVar(player, 'Prog', 6)\n                    end\n\n                    for i = mamookID.mob.POROGGO_CASANOVA + 1, mamookID.mob.POROGGO_CASANOVA + 5 do\n                        DespawnMob(i)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 3 then\n                    return 227\n                end\n            end,\n\n            onEventFinish =\n            {\n                [222] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    -- Zone the person to Wajaom for second part of cs\n                    player:setPos(610.542, -28.547, 356.247, 0, xi.zone.WAJAOM_WOODLANDS)\n                end,\n\n                [223] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n\n                [225] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 7)\n                end,\n\n                [227] = function(player, csid, option, npc) -- end of 2nd zone in cutscene\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Maudaal'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 7 then\n                        return quest:progressEvent(890)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [890] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Three_Men_and_a_Closet.lua"]={["Path"]="scripts/quests/ahtUrhgan/Three_Men_and_a_Closet.lua",["SHA256"]="68610b8b40d8e7c456ddde0a97c1dac9de404b5e608bcf6f4424e7822a7070fa",["Text"]="-----------------------------------\n-- Three Men and a Closet\n-- Kubhe Ijyuhla !pos 23.257 0 21.532 50\n-- Ratihb !pos 75 -6 -135 50\n-- Tehf Kimasnahya !pos -89.897 -1 6.199 50\n-- Ekhu Pesshyadha !pos -13.043 0.999 103.423 50\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.THREE_MEN_AND_A_CLOSET)\n\nquest.reward =\n{\n    item = xi.item.IMPERIAL_BRONZE_PIECE,\n}\n\nquest.sections =\n{\n    -- Section: Begin quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.GOT_IT_ALL) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Kubhe_Ijyuhla'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(836)\n                end\n            },\n\n            onEventFinish =\n            {\n                [836] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Questing\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Kubhe_Ijyuhla'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        return quest:event(837)\n                    elseif progress == 1 then\n                        return quest:progressEvent(838)\n                    elseif progress == 2 then\n                        return quest:event(839)\n                    elseif progress == 3 then\n                        return quest:event(842)\n                    elseif progress == 4 then\n                        return quest:progressEvent(845)\n                    end\n                end,\n            },\n\n            ['Tehf_Kimasnahya'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 3 then\n                        return quest:progressEvent(843)\n                    elseif progress == 4 then\n                        return quest:event(844)\n                    end\n                end,\n            },\n\n            ['Ratihb'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 2 then\n                        return quest:progressEvent(840)\n                    elseif progress == 3 then\n                        return quest:event(841)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [838] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [840] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [843] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'Prog', 4)\n                    end\n                end,\n\n                [845] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.AHT_URHGAN_WHITEGATE and\n                    quest:getVar(player, 'Prog') == 0\n                then\n                    return 510\n                end\n            end,\n\n            onEventFinish =\n            {\n                [510] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    -- Section: Completed quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Kubhe_Ijyuhla'] = quest:event(846),\n            ['Tehf_Kimasnahya'] = quest:event(844),\n        }\n    }\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Two_Horn_the_Savage.lua"]={["Path"]="scripts/quests/ahtUrhgan/Two_Horn_the_Savage.lua",["SHA256"]="f0e32eef86b98347fdb72998f6a8773073f40beb65dd813106d9dfa9624cd591",["Text"]="-----------------------------------\n-- Two Horn the Savage\n-----------------------------------\n-- Log ID: 6, Quest ID: 17\n-----------------------------------\n-- !zone 50       = Whitegate\n-- Milazahn       = !pos -58.1921 0.000 1.9746\n-- Cacaroon       = !pos -71.1544 0.000 -86.0422\n-- !zone 65       = Mamook\n-- Viscous Liquid = !pos -262.437 5.130 -141.241\n-----------------------------------\nlocal ID = zones[xi.zone.MAMOOK]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.TWO_HORN_THE_SAVAGE)\n\nquest.reward =\n{\n    item = xi.item.IMPERIAL_MYTHRIL_PIECE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Milazahn'] = quest:progressEvent(594),\n\n            onEventFinish =\n            {\n                [594] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Cacaroon'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') >= 1 then\n                        return quest:event(608):oncePerZone()\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        npcUtil.tradeHasExactly(trade, { { 'gil', 1000 } })\n                    then\n                        return quest:progressEvent(595)\n                    end\n                end,\n            },\n\n            ['Milazahn'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:progressEvent(596)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [596] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n\n                [595] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.MAMOOK] =\n        {\n            ['Viscous_Liquid'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if npc:getID() == ID.npc.QUEST_LIQUID then\n                        if progress == 1 then\n                            return quest:progressEvent(212)\n                        elseif\n                            progress == 2 and\n                            npcUtil.popFromQM(player, npc, ID.mob.MAMOOL_JA, { claim = true, hide = 0 })\n                        then\n                            return quest:messageSpecial(ID.text.IMPENDING_BATTLE)\n                        elseif progress == 3 then\n                            return quest:progressEvent(213)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [212] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [213] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n\n            ['Mamool_Ja'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        quest:setVar(player, 'Prog', 3) -- Zoning will NOT reset progress. Progress is gained and kept as long as the NM has died.\n                    end\n                end,\n            },\n        },\n\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Vanishing_Act.lua"]={["Path"]="scripts/quests/ahtUrhgan/Vanishing_Act.lua",["SHA256"]="504abf4818d07a01671bffac87fa71c2ae5445f247d826a59d2b3c998d73370f",["Text"]="-----------------------------------\n-- Vanishing Act\n-- Ulamaal, Whitegate, !pos 93 -7.5 -128 50\n-- Fochacha, Whitegate , !pos 3 -1 -10.781 50\n-- Qutiba, Whitegate, !pos 92 -7.5 -130 50\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.VANISHING_ACT)\n\nquest.reward =\n{\n    item = xi.item.IMPERIAL_SILVER_PIECE\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.DELIVERING_THE_GOODS)\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Qutiba'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:needToZone() or\n                        quest:getVar(player, 'Stage') > GetSystemTime()\n                    then\n                        return quest:event(52)\n                    end\n\n                    return quest:progressEvent(42) -- Starts Quest\n                end,\n            },\n\n            ['Ulamaal'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:needToZone() or quest:getVar(player, 'Stage') > GetSystemTime() then\n                        return quest:event(53)\n                    end\n\n                    return quest:progressEvent(42) -- Starts Quest\n                end,\n            },\n\n            ['Fochacha'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(47)\n                end\n            },\n\n            onEventFinish =\n            {\n                [42] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Stage', 0)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fochacha'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        return quest:progressEvent(43)\n                    elseif progress == 1 then\n                        return quest:event(48)\n                    end\n\n                    return quest:event(49)\n                end,\n            },\n\n            ['Ulamaal'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.RAINBOW_BERRY) then\n                        return quest:progressEvent(45)\n                    else\n                        return quest:event(54)\n                    end\n                end,\n            },\n\n            ['Qutiba'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.RAINBOW_BERRY) then\n                        return quest:progressEvent(45)\n                    else\n                        return quest:event(54)\n                    end\n                end,\n            },\n\n            onTriggerAreaEnter =\n            {\n                [2] = function(player, triggerArea)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(44)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [43] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [44] = function(player, csid, option, npc)\n                    player:setPos(-80, -6, 122, 5)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [45] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:needToZone(true)\n                        player:delKeyItem(xi.keyItem.RAINBOW_BERRY)\n                        xi.quest.setVar(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.A_TASTE_OF_HONEY, 'Stage', GetSystemTime() + 60) -- 1 minute wait time\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            ['Harvesting_Point'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeMatches(trade, { { xi.item.SICKLE, 1 } }) and\n                        quest:getVar(player, 'Prog') == 2 and\n                        not player:hasKeyItem(xi.keyItem.RAINBOW_BERRY)\n                    then\n                        player:setLocalVar('questItem', 1)\n                        return quest:progressEvent(507, { [0] = 4294966520 })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [507] = function(player, csid, option, npc)\n                    if player:getLocalVar('questItem') == 1 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.RAINBOW_BERRY)\n                        player:setLocalVar('questItem', 0)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ulamaal'] =\n            {\n                onTrigger = function(player, npc)\n                    player:setLocalVar('recipe', 58)\n                    return quest:event(58)\n                end,\n            },\n\n            ['Fochacha'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(59)\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [58] = function(player, csid, option, npc)\n                    if player:getLocalVar('recipe') == 58 then\n                        player:setLocalVar('recipe', 1)\n                        player:updateEvent(5579, 1, 255, 0, 67108863, 5976652, 4095, 0)\n                    elseif player:getLocalVar('recipe') == 1 then\n                        player:setLocalVar('recipe', 2)\n                        player:updateEvent(4096, 615, 936, 1523, 67108863, 5976652, 4, 0)\n                    elseif player:getLocalVar('recipe') == 2 then\n                        player:setLocalVar('recipe', 3)\n                        player:updateEvent(2214, 2237, 4509, 5568)\n                    elseif player:getLocalVar('recipe') == 3 then\n                        player:setLocalVar('recipe', 0)\n                        player:updateEvent(5575)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Waking_the_Colossus.lua"]={["Path"]="scripts/quests/ahtUrhgan/Waking_the_Colossus.lua",["SHA256"]="d8cf7e30e5763ed893ca44776edd37397e8756410648236173f7a5ac87d37ffb",["Text"]="-----------------------------------\n-- Waking the Colossus\n-----------------------------------\n-- Log ID: 6, Quest ID: 74\n-- Naja Salaheem, !pos 22.700 -8.804 -45.591 50\n-- Imperial Whitegate, !pos 152.8295 -2.2 0.0613 50\n-- Audience Chamber, !pos 0 -5 66 243\n-- Halver !pos 2.4 0 0 233\n-- Iron Eater !pos 91 -19 1 237\n-- Kupipi !pos 2 0 30 242\n-- Audience Chamber, !pos 0 -5 66 243\n-- Imperial Whitegate, !pos 152.8295 -2.2 0.0613 50\n-- Acid-Eaten Door, !pos 271.9045 -32 -88 61\n-- Blank Lamp, !pos 209.3953 0.05 20.0207 72\n-- Runic Seal, !pos 125.4569 0 19.9914 72\n-- Imperial Whitegate, !pos 152.8295 -2.2 0.0613 50\n-- Naja Salaheem, !pos 22.700 -8.804 -45.591 50\n-----------------------------------\nlocal ahtUrhganID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.WAKING_THE_COLOSSUS)\n\nquest.reward =\n{\n    title = xi.title.HEIR_OF_THE_BLESSED_RADIANCE,\n    item  = { xi.item.IMPERIAL_GOLD_PIECE }\n}\n\nlocal rewardItems =\n{\n    [0] = xi.item.COLOSSUSS_MANTLE,\n    [1] = xi.item.COLOSSUSS_EARRING,\n    [2] = xi.item.COLOSSUSS_TORQUE,\n}\n\nlocal function getRewardMask(player)\n    local rewardMask = 0\n\n    for bitNum, itemId in pairs(rewardItems) do\n        if player:hasItem(itemId) then\n            rewardMask = utils.mask.setBit(rewardMask, bitNum, true)\n        end\n    end\n\n    if player:hasSpell(xi.magic.spell.ALEXANDER) then\n        rewardMask = utils.mask.setBit(rewardMask, 4, true)\n    end\n\n    return rewardMask\nend\n\nlocal function giveQuestReward(player, eventOption)\n    local wasRewarded = true\n\n    if eventOption <= 3 then\n        wasRewarded = npcUtil.giveItem(player, rewardItems[eventOption - 1])\n    elseif eventOption == 4 then\n        npcUtil.giveCurrency(player, 'gil', 10000)\n    elseif eventOption == 5 then\n        player:addSpell(xi.magic.spell.ALEXANDER)\n        player:messageSpecial(ahtUrhganID.text.ALEXANDER_UNLOCKED, 0, 0, 1)\n    end\n\n    return wasRewarded\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getCurrentMission(xi.mission.log_id.TOAU) == xi.mission.id.toau.ETERNAL_MERCENARY\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Imperial_Whitegate'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        not player:hasKeyItem(xi.keyItem.IMPERIAL_MISSIVE)\n                    then\n                        return quest:progressEvent(926, { text_table = 0, [0] = 50, [1] = 1, [2] = 4, [5] = 1 })\n                    end\n                end,\n            },\n\n            onTriggerAreaEnter =\n            {\n                [13] = function(player, triggerArea)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(925, { text_table = 0, [0] = 50, [1] = 1, [2] = 4, [5] = 1 })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [925] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [926] = function(player, csid, option, npc)\n                    if option == 0 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.IMPERIAL_MISSIVE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:hasKeyItem(xi.keyItem.IMPERIAL_MISSIVE)\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['_6r9'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(10115)\n                    end\n\n                    if\n                        not player:hasKeyItem(xi.keyItem.JEUNOAN_APPROVAL_LETTER) and\n                        player:hasKeyItem(xi.keyItem.SAN_DORIAN_APPROVAL_LETTER) and\n                        player:hasKeyItem(xi.keyItem.BASTOKAN_APPROVAL_LETTER) and\n                        player:hasKeyItem(xi.keyItem.WINDURSTIAN_APPROVAL_LETTER)\n                    then\n                        return quest:progressEvent(10116)\n                    end\n                end\n            },\n\n            onEventFinish =\n            {\n                [10115] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [10116] = function(player, csid, option, npc)\n                    if option == 0 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.JEUNOAN_APPROVAL_LETTER)\n                    end\n                end,\n            }\n        },\n\n        [xi.zone.CHATEAU_DORAGUILLE] =\n        {\n            ['Halver'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        not player:hasKeyItem(xi.keyItem.SAN_DORIAN_APPROVAL_LETTER)\n                    then\n                        return quest:progressEvent(567, { [0] = 4, [1] = 4, [2] = 2964, [6] = 1 })\n                    end\n                end\n            },\n\n            onEventFinish =\n            {\n                [567] = function(player, csid, option, npc)\n                    if option == 0 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.SAN_DORIAN_APPROVAL_LETTER)\n                    end\n                end,\n            }\n        },\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Iron_Eater'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        not player:hasKeyItem(xi.keyItem.BASTOKAN_APPROVAL_LETTER)\n                    then\n                        return quest:progressEvent(968, { [1] = 4, [2] = 2964, [4] = 58195967, [5] = 212046073, [7] = 4095 })\n                    end\n                end\n            },\n\n            onEventFinish =\n            {\n                [968] = function(player, csid, option, npc)\n                    if option == 0 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.BASTOKAN_APPROVAL_LETTER)\n                    end\n                end,\n            }\n        },\n\n        [xi.zone.HEAVENS_TOWER] =\n        {\n            ['Kupipi'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        not player:hasKeyItem(xi.keyItem.WINDURSTIAN_APPROVAL_LETTER)\n                    then\n                        return quest:progressEvent(429, { [0] = 74, [1] = 4, [2] = 2964, [4] = 582, [7] = 1 })\n                    end\n                end\n            },\n\n            onEventFinish =\n            {\n                [429] = function(player, csid, option, npc)\n                    if option == 0 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WINDURSTIAN_APPROVAL_LETTER)\n                    end\n                end,\n            }\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:hasKeyItem(xi.keyItem.JEUNOAN_APPROVAL_LETTER)\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Imperial_Whitegate'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.PRESENT_FOR_MEGOMAK) then\n                        return quest:progressEvent(927, { text_table = 0, [2] = 3, [4] = 66420735, [5] = 66497777 })\n                    end\n                end\n            },\n\n            onEventFinish =\n            {\n                [927] = function(player, csid, option, npc)\n                    if option == 0 then\n                        player:delKeyItem(xi.keyItem.IMPERIAL_MISSIVE)\n                        player:delKeyItem(xi.keyItem.SAN_DORIAN_APPROVAL_LETTER)\n                        player:delKeyItem(xi.keyItem.BASTOKAN_APPROVAL_LETTER)\n                        player:delKeyItem(xi.keyItem.WINDURSTIAN_APPROVAL_LETTER)\n                        player:delKeyItem(xi.keyItem.JEUNOAN_APPROVAL_LETTER)\n                        npcUtil.giveKeyItem(player, xi.keyItem.PRESENT_FOR_MEGOMAK)\n                    end\n                end,\n            }\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                (player:hasKeyItem(xi.keyItem.PRESENT_FOR_MEGOMAK) or player:hasKeyItem(xi.keyItem.MEGOMAKS_SHOPPING_LIST))\n        end,\n\n        [xi.zone.MOUNT_ZHAYOLM] =\n        {\n            ['Acid-eaten_Door'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.PRESENT_FOR_MEGOMAK) and\n                        not player:hasKeyItem(xi.keyItem.MEGOMAKS_SHOPPING_LIST)\n                    then\n                        return quest:progressEvent(154)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        player:hasKeyItem(xi.keyItem.MEGOMAKS_SHOPPING_LIST) and\n                        npcUtil.tradeHasExactly(trade, { { xi.item.SLAB_OF_PLUMBAGO, 3 } }) and\n                        not player:hasKeyItem(xi.keyItem.LIGHTNING_CELL)\n                    then\n                        return quest:progressEvent(155)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [154] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:delKeyItem(xi.keyItem.PRESENT_FOR_MEGOMAK)\n                        npcUtil.giveKeyItem(player, xi.keyItem.MEGOMAKS_SHOPPING_LIST)\n                    end\n                end,\n\n                [155] = function(player, csid, option, npc)\n                    if npcUtil.giveKeyItem(player, xi.keyItem.LIGHTNING_CELL) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        }\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                (player:hasKeyItem(xi.keyItem.LIGHTNING_CELL) or vars.Prog == 4)\n        end,\n\n        [xi.zone.ALZADAAL_UNDERSEA_RUINS] =\n        {\n            ['blank_lamp'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.LIGHTNING_CELL) and\n                        quest:getVar(player, 'Prog') == 2\n                    then\n                        return quest:progressEvent(306)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if\n                    quest:getVar(player, 'Prog') == 4 and\n                    not player:hasKeyItem(xi.keyItem.WHISPER_OF_RADIANCE)\n                then\n                    return 307\n                end\n            end,\n\n            onEventFinish =\n            {\n                [306] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [307] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.WHISPER_OF_RADIANCE)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:hasKeyItem(xi.keyItem.WHISPER_OF_RADIANCE)\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Imperial_Whitegate'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:progressEvent(928, { text_table = 0, [2] = 255, [4] = 67108863, [5] = 47467207 })\n                    end\n                end,\n            },\n            ['Naja_Salaheem'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 5 then\n                        return quest:progressEvent(929, { text_table = 0, [0] = xi.besieged.getMercenaryRank(player), [7] = getRewardMask(player) })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [928] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 5)\n                    end\n                end,\n\n                [929] = function(player, csid, option, npc)\n                    if giveQuestReward(player, option) then\n                        quest:complete(player)\n                        player:delKeyItem(xi.keyItem.WHISPER_OF_RADIANCE)\n                        -- Divine Interference cannot start until next JP midnight\n                        xi.quest.setVar(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.DIVINE_INTERFERENCE, 'Timer', 1, NextJstDay())\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/What_Friends_Are_For.lua"]={["Path"]="scripts/quests/ahtUrhgan/What_Friends_Are_For.lua",["SHA256"]="69506a6136cbbf02ebfa22742e2efef27f53f0c46e6dd146ab13caf7f80e38a2",["Text"]="-----------------------------------\n-- What Friends Are For\n-- Region !pos -389 13 -445 68\n-- Tsetseroon !pos -13 -6 69 53\n-- Qm9 !pos -406 6.5 -440 68\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.WHAT_FRIENDS_ARE_FOR)\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and vars.Prog == 0\n        end,\n\n        [xi.zone.AYDEEWA_SUBTERRANE] =\n        {\n            onTriggerAreaEnter =\n            {\n                [2] = function(player, triggerArea)\n                    return quest:progressEvent(7)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [7] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Tsetseroon'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(4)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest available, step 2\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and vars.Prog == 1\n        end,\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Tsetseroon'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(16)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [16] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Tsetseroon'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:event(17)\n                    elseif quest:getVar(player, 'Prog') == 3 then\n                        return quest:event(19)\n                    elseif quest:getVar(player, 'Prog') == 4 then\n                        return quest:progressEvent(20)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        npcUtil.tradeHasExactly(trade, { xi.item.CHUNK_OF_TIN_ORE, xi.item.COBALT_JELLYFISH })\n                    then\n                        return quest:progressEvent(18)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [18] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.POT_OF_TSETSEROONS_STEW)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [20] = function(player, csid, option, npc)\n                    if player:hasKeyItem(xi.keyItem.MAP_OF_AYDEEWA_SUBTERRANE) then\n                        if npcUtil.giveItem(player, xi.item.IMPERIAL_BRONZE_PIECE) then\n                            quest:complete(player)\n                        end\n                    else\n                        if quest:complete(player) then\n                            npcUtil.giveKeyItem(player, xi.keyItem.MAP_OF_AYDEEWA_SUBTERRANE)\n                        end\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.AYDEEWA_SUBTERRANE] =\n        {\n            ['qm9'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 3 and\n                        player:hasKeyItem(xi.keyItem.POT_OF_TSETSEROONS_STEW)\n                    then\n                        return quest:progressEvent(8)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [8] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                    player:delKeyItem(xi.keyItem.POT_OF_TSETSEROONS_STEW)\n                    if option == 1 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.MAP_OF_AYDEEWA_SUBTERRANE)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Tsetseroon'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(21)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"}};
